from lib import *
S = SS('h22')
steps = [
    step("服务端 status.New(InvalidArgument, “参数不合法”).WithDetails(ErrorInfo{reason: BAD_NAME, domain: demo.example, metadata: {field: name}}):线上 trailers 里有三个头——grpc-status: 3,grpc-message: %E5%8F%82%E6%95%B0…(中文被百分号编码),grpc-status-details-bin: CAMS…(共 164 字符,是 google.rpc.Status 序列化后再 base64)。客户端 status.FromError 得到 code=InvalidArgument、message、details 1 个,类型断言成 *errdetails.ErrorInfo 后取到 reason、domain、metadata。details 走的是 -bin 结尾的 trailer,所以可以放任意二进制。", t=tl(S(1)), done=lidx(S(1), 'ErrorInfo: reason'), mark=lidx(S(1), '线上 trailers'), b=bars([['trailers 里 grpc- 开头的头个数', 3, '3'], ['客户端取到的 details 个数', 1, '1']], 4, mark=[0], done=[1]), kv=KV([['grpc-status', '3(InvalidArgument)'], ['grpc-message', '百分号编码的文本'], ['grpc-status-details-bin', 'google.rpc.Status 的 base64,164 字符']], ['grpc-status-details-bin'])),
    step("一个错误可以带多种 details:这次带了 ErrorInfo(reason: QUOTA)、BadRequest(两个字段错误:n 必须小于 10、msg 不能为空)、RetryInfo(建议等待 1.5 秒)。客户端 details 个数 3,按类型分别取出。线上 grpc-status-details-bin 变成 333 字符。这些类型来自 google.golang.org/genproto/googleapis/rpc/errdetails,是 Google 定的一套标准错误详情,客户端用类型断言就知道怎么处理(比如读 RetryInfo 决定多久后重试)。", t=tl(S(2)), done=lidx(S(2), '线上 trailers'), mark=lidx(S(2), 'details 个数 3'), b=bars([['details 个数', 3, '3'], ['BadRequest 里的字段错误', 2, '2']], 4, mark=[0], done=[1]), kv=KV([['ErrorInfo', 'reason / domain / metadata'], ['BadRequest', '每个字段一条错误描述'], ['RetryInfo', '建议等待 1.5 秒']], ['RetryInfo'])),
    step("details 越大,trailers 越大:ErrorInfo.metadata 里放 1 KiB、64 KiB、1024 KiB 的值时,线上 grpc-status-details-bin 分别是 1497、87519、1398239 个字符,客户端都成功取到 details 1 个;放 20480 KiB(20 MiB)时,客户端收到 Unavailable“error reading from server: connection error: COMPRESSION_ERROR”,details 为 0——trailers 超过了客户端的头部大小上限(读源码:defaultClientMaxHeaderListSize = 16 MiB),连接出错。结论:details 不要放大块数据;上限在 1 MiB 到 20 MiB 之间(没有进一步二分)。", t=tl(S(3)), done=lidx(S(3), '20480 KiB'), mark=lidx(S(3), '    1 KiB'), b=bars([['1 KiB 的线上字符数', 1497, '1497'], ['64 KiB', 87519, '87519'], ['1024 KiB', 1398239, '1398239']], 1500000, mark=[0], done=[1, 2]), kv=KV([['1 MiB 以内', '正常取到 details'], ['20 MiB', 'COMPRESSION_ERROR,连接出错'], ['原因', '超过头部大小上限(16 MiB)']], ['20 MiB'])),
    step("不能带 details 的情形:对 code 为 OK 的 status 调用 WithDetails 返回错误“no error details for status with code OK”。详情里放了客户端不认识的类型(type.googleapis.com/nope.Thing):客户端 code=NotFound、message 正常,Details() 返回 1 项,但这一项是 error(“proto: not found”),不是消息——解析不了的详情以 error 的形式混在列表里,所以遍历 Details() 时要先判断是不是 error。", t=tl(S(4)), done=lidx(S(4), '不认识的类型'), mark=lidx(S(4), 'status.New(codes.OK)'), b=bars([['OK 状态能带的 details 个数', 0, '0(报错)'], ['不认识的类型:Details() 里的 error 项', 1, '1']], 1.5, mark=[0], done=[1]), kv=KV([['OK + WithDetails', '返回错误'], ['不认识的类型', 'Details() 里是 error 项'], ['遍历时', '先判断是不是 error']], ['不认识的类型'])),
    step("服务 A 调用服务 B,B 返回带 details 的 FailedPrecondition。A 直接 return err:客户端看到 code=FailedPrecondition、message=“B 的错误”、details 里还有 FROM_B;A 用 status.Convert(err).Err() 重新包装:结果相同;A 用 fmt.Errorf(\"A: %w\", err) 包一层:code 仍是 FailedPrecondition、details 仍在,但 message 变成了“A: rpc error: code = FailedPrecondition desc = B 的错误”(整句错误文本被带进去了)。在这个版本(grpc-go v1.84.0)里 status.FromError 会解开 %w 包装拿到状态,但 message 是整个 error.Error()。详情会随错误一路透传,不需要额外代码;但要小心:把 B 的内部细节(details)原样转给外部客户端可能不合适(第 41 篇)。", t=tl(S(5)), done=lidx(S(5), 'fmt.Errorf'), mark=lidx(S(5), '直接 return err'), b=bars([['直接 return:客户端取到 FROM_B(1=是)', 1, '是'], ['Convert 重新包装', 1, '是'], ['fmt.Errorf %w 包装', 1, '是(message 变长)']], 1.2, done=[0, 1, 2]), kv=KV([['直接 return err', 'code、message、details 原样'], ['status.Convert(err).Err()', '同上'], ['fmt.Errorf(\"A: %w\")', 'code、details 保留,message 变成整句']], ['fmt.Errorf(\"A: %w\")'])),
]
A = mkarth('h22', 22, 'gRPC,错误详情,google.rpc.Status,errdetails,ErrorInfo,BadRequest,grpc-status-details-bin,Go,真实验证,动画演示',
    '实测 gRPC 的错误详情:details 走 trailers 里的 grpc-status-details-bin;一个错误可以带 ErrorInfo、BadRequest、RetryInfo 等多种标准类型;details 太大(20 MiB)连接会出错;不认识的类型变成 error 项;A 调 B 时 details 如何透传。',
    'gRPC 的状态码只有 17 个,业务上要告诉客户端“哪个字段错了”“多久后再试”怎么办?答案是 google.rpc.Status 的 details。这篇看它在线上长什么样、能带多大、跨服务时会不会丢。',
    [('3 个头', 'trailers 里 grpc-status、grpc-message、grpc-status-details-bin'), ('1 MiB 可以 / 20 MiB 不行', 'details 太大时客户端的表现(COMPRESSION_ERROR)'), ('code、details 保留', 'A 用 fmt.Errorf("%w") 包装 B 的错误后客户端看到的')],
    [('details 在哪', '<p>google.rpc.Status(code、message、details 列表)被序列化后放在 trailer grpc-status-details-bin 里,与 grpc-status、grpc-message 并存。</p>'),
     ('标准类型', '<p>errdetails 包提供 ErrorInfo(原因、域、键值)、BadRequest(字段错误)、RetryInfo(重试建议)等,客户端按类型处理。一个错误可以带多个。</p>'),
     ('大小', '<p>details 在 trailers 里,受头部大小限制(客户端默认约 16 MiB);1 MiB 以内正常,20 MiB 连接出错。不要放大块数据。</p>'),
     ('边界情况', '<p>OK 状态不能带 details;客户端不认识的类型在 Details() 里以 error 的形式出现。</p>'),
     ('跨服务透传', '<p>直接返回下游的错误,details 会原样传给上游客户端;用 %w 包装也保留 code 和 details,但 message 会变成整句错误文本。</p>')],
    steps,
    [ENV_H + '。线上的 trailers 来自抓包代理;details 类型用 google.golang.org/genproto/googleapis/rpc/errdetails;头部大小上限读自 internal/transport/defaults.go;“20 MiB 失败、1 MiB 成功”之间没有做二分;A 调 B 是同一进程里的两个本机服务',
     '没有验证:其它 errdetails 类型(PreconditionFailure、QuotaFailure、Help、LocalizedMessage 等);其它语言客户端对 details 的解析;经过 grpc-gateway 转 JSON 时 details 的样子(第 29 篇);details 对重试的影响;服务端设置的 MaxHeaderListSize 对 trailers 的限制'],
    '错误详情')
